#!/usr/bin/env python3
"""Minimal dependency-free Chrome DevTools Protocol driver used only to test ./index.html.

Usage:
  cdp.py sheet  <out.png> <t0,t1,...> [--cols N] [--cell WxH] [--crop x,y,w,h] [--size WxH]
  cdp.py shot   <out.png> <t> [--size WxH] [--clip x,y,w,h]
  cdp.py eval   <js-file-or-expr> [--size WxH] [--wait S]
"""
import base64, json, os, socket, struct, subprocess, sys, tempfile, time, urllib.request, shutil

CHROME = os.path.expanduser(
    "~/Library/Caches/ms-playwright/chromium-1254/chrome-mac-arm64/"
    "Google Chrome for Testing.app/Contents/MacOS/Google Chrome for Testing")
PAGE = "file:///private/tmp/pcd-sbx-claude-fable-5.2-j0jae637/work/index.html"


class WS:
    def __init__(self, url):
        rest = url[len("ws://"):]
        hostport, path = rest.split("/", 1)
        host, port = hostport.split(":")
        self.s = socket.create_connection((host, int(port)))
        key = base64.b64encode(os.urandom(16)).decode()
        req = ("GET /%s HTTP/1.1\r\nHost: %s\r\nUpgrade: websocket\r\nConnection: Upgrade\r\n"
               "Sec-WebSocket-Key: %s\r\nSec-WebSocket-Version: 13\r\n\r\n" % (path, hostport, key))
        self.s.sendall(req.encode())
        buf = b""
        while b"\r\n\r\n" not in buf:
            buf += self.s.recv(4096)
        self.buf = buf.split(b"\r\n\r\n", 1)[1]

    def send(self, text):
        data = text.encode()
        n = len(data)
        hdr = bytearray([0x81])
        if n < 126:
            hdr.append(0x80 | n)
        elif n < 65536:
            hdr.append(0x80 | 126)
            hdr += struct.pack(">H", n)
        else:
            hdr.append(0x80 | 127)
            hdr += struct.pack(">Q", n)
        mask = os.urandom(4)
        hdr += mask
        m = (mask * (n // 4 + 1))[:n]
        masked = (int.from_bytes(data, "big") ^ int.from_bytes(m, "big")).to_bytes(n, "big") if n else b""
        self.s.sendall(bytes(hdr) + masked)

    def _read(self, n):
        while len(self.buf) < n:
            chunk = self.s.recv(1 << 20)
            if not chunk:
                raise EOFError("socket closed")
            self.buf += chunk
        out, self.buf = self.buf[:n], self.buf[n:]
        return out

    def recv(self):
        msg = b""
        while True:
            b0, b1 = self._read(2)
            fin, op = b0 & 0x80, b0 & 0x0F
            n = b1 & 0x7F
            if n == 126:
                n = struct.unpack(">H", self._read(2))[0]
            elif n == 127:
                n = struct.unpack(">Q", self._read(8))[0]
            if b1 & 0x80:
                self._read(4)
            payload = self._read(n)
            if op == 8:
                raise EOFError("ws closed")
            if op in (9, 10):
                continue
            msg += payload
            if fin:
                return msg.decode("utf-8", "replace")


class Browser:
    def __init__(self, width=1920, height=1080, extra=()):
        self.profile = tempfile.mkdtemp(prefix="pcd-prof-", dir=os.environ.get("TMPDIR"))
        s = socket.socket()
        s.bind(("127.0.0.1", 0))
        self.port = s.getsockname()[1]
        s.close()
        args = [CHROME, "--headless=new", "--remote-debugging-port=%d" % self.port,
                "--user-data-dir=" + self.profile, "--no-first-run", "--no-default-browser-check",
                "--hide-scrollbars", "--mute-audio", "--window-size=%d,%d" % (width, height),
                "--ignore-gpu-blocklist", "--enable-webgl", "--allow-file-access-from-files",
                "--disable-background-timer-throttling", "--disable-renderer-backgrounding",
                "--disable-backgrounding-occluded-windows"] + list(extra) + ["about:blank"]
        self.proc = subprocess.Popen(args, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        target = None
        for _ in range(100):
            try:
                with urllib.request.urlopen("http://127.0.0.1:%d/json" % self.port, timeout=1) as r:
                    for t in json.loads(r.read().decode()):
                        if t.get("type") == "page":
                            target = t
                            break
                if target:
                    break
            except Exception:
                pass
            time.sleep(0.1)
        if not target:
            raise RuntimeError("chrome did not start")
        self.ws = WS(target["webSocketDebuggerUrl"])
        self.id = 0
        self.events = []
        self.call("Page.enable")
        self.call("Runtime.enable")
        self.call("Log.enable")
        self.call("Emulation.setDeviceMetricsOverride",
                  {"width": width, "height": height, "deviceScaleFactor": 1, "mobile": False})

    def call(self, method, params=None, timeout=120):
        self.id += 1
        mid = self.id
        self.ws.send(json.dumps({"id": mid, "method": method, "params": params or {}}))
        self.ws.s.settimeout(timeout)
        while True:
            m = json.loads(self.ws.recv())
            if m.get("id") == mid:
                if "error" in m:
                    raise RuntimeError("%s: %s" % (method, m["error"]))
                return m.get("result", {})
            self.events.append(m)

    def pump(self, seconds):
        end = time.time() + seconds
        while time.time() < end:
            self.ws.s.settimeout(max(0.01, end - time.time()))
            try:
                self.events.append(json.loads(self.ws.recv()))
            except socket.timeout:
                break
            except Exception:
                break

    def navigate(self, url=PAGE, settle=2.0):
        self.call("Page.navigate", {"url": url})
        self.pump(settle)

    def evaluate(self, expr, await_promise=True):
        r = self.call("Runtime.evaluate", {"expression": expr, "awaitPromise": await_promise,
                                             "returnByValue": True, "userGesture": True})
        if "exceptionDetails" in r:
            raise RuntimeError("JS exception: " + json.dumps(r["exceptionDetails"])[:2000])
        return r.get("result", {}).get("value")

    def screenshot(self, path, clip=None):
        p = {"format": "png"}
        if clip:
            p["clip"] = {"x": clip[0], "y": clip[1], "width": clip[2], "height": clip[3], "scale": 1}
        r = self.call("Page.captureScreenshot", p)
        with open(path, "wb") as f:
            f.write(base64.b64decode(r["data"]))

    def console(self):
        out = []
        for e in self.events:
            m = e.get("method")
            if m == "Runtime.consoleAPICalled":
                p = e["params"]
                txt = " ".join(str(a.get("value", a.get("description", ""))) for a in p.get("args", []))
                out.append("[console.%s] %s" % (p.get("type"), txt))
            elif m == "Runtime.exceptionThrown":
                d = e["params"]["exceptionDetails"]
                out.append("[exception] %s %s (line %s)" % (
                    d.get("text"), (d.get("exception") or {}).get("description", ""), d.get("lineNumber")))
            elif m == "Log.entryAdded":
                en = e["params"]["entry"]
                out.append("[log.%s] %s %s" % (en.get("level"), en.get("text"), en.get("url", "")))
        return out

    def close(self):
        try:
            self.call("Browser.close", timeout=5)
        except Exception:
            pass
        try:
            self.proc.wait(timeout=5)
        except Exception:
            self.proc.kill()
        shutil.rmtree(self.profile, ignore_errors=True)


SHEET_JS = r"""
(async () => {
  const times = %(times)s, cols = %(cols)d, cw = %(cw)d, ch = %(ch)d, crop = %(crop)s;
  const stage = document.getElementById('stage'), sc = document.getElementById('scrubber');
  const rows = Math.ceil(times.length / cols);
  const sheet = document.createElement('canvas');
  sheet.width = cols * cw; sheet.height = rows * ch;
  const ctx = sheet.getContext('2d');
  for (let i = 0; i < times.length; i++) {
    sc.value = String(times[i]);
    sc.dispatchEvent(new Event('input', { bubbles: true }));
    const x = (i %% cols) * cw, y = Math.floor(i / cols) * ch;
    const g = ctx.createRadialGradient(x + cw / 2, y + ch / 2, 0, x + cw / 2, y + ch / 2, Math.hypot(cw, ch) / 2);
    g.addColorStop(0, '#161922'); g.addColorStop(1, '#090a0f');
    ctx.fillStyle = g; ctx.fillRect(x, y, cw, ch);
    if (crop) ctx.drawImage(stage, crop[0], crop[1], crop[2], crop[3], x, y, cw, ch);
    else ctx.drawImage(stage, x, y, cw, ch);
    ctx.fillStyle = 'rgba(255,255,255,0.85)'; ctx.font = '13px monospace';
    ctx.fillText('t=' + Number(times[i]).toFixed(3), x + 6, y + 16);
    ctx.strokeStyle = 'rgba(255,255,255,0.15)'; ctx.strokeRect(x + 0.5, y + 0.5, cw - 1, ch - 1);
  }
  return sheet.toDataURL('image/png');
})()
"""


def opt(args, name, default=None):
    if name in args:
        i = args.index(name)
        v = args[i + 1]
        del args[i:i + 2]
        return v
    return default


def main():
    args = sys.argv[1:]
    mode = args.pop(0)
    size = opt(args, "--size", "1920x1080")
    W, H = [int(v) for v in size.split("x")]
    extra = []
    if opt(args, "--swiftshader", None) is not None:
        extra += ["--use-angle=swiftshader", "--enable-unsafe-swiftshader"]
    b = Browser(W, H, extra)
    try:
        b.navigate(settle=float(opt(args, "--settle", "2.5")))
        if mode == "sheet":
            out, times = args[0], [float(v) for v in args[1].split(",")]
            cols = int(opt(args, "--cols", "3"))
            cw, ch = [int(v) for v in opt(args, "--cell", "640x360").split("x")]
            crop = opt(args, "--crop", None)
            crop_js = "[" + crop + "]" if crop else "null"
            data = b.evaluate(SHEET_JS % {"times": json.dumps(times), "cols": cols, "cw": cw, "ch": ch,
                                          "crop": crop_js})
            with open(out, "wb") as f:
                f.write(base64.b64decode(data.split(",", 1)[1]))
            print("wrote", out)
        elif mode == "shot":
            out, t = args[0], args[1]
            clip = opt(args, "--clip", None)
            if t != "live":
                b.evaluate("(()=>{const s=document.getElementById('scrubber');s.value='%s';"
                           "s.dispatchEvent(new Event('input',{bubbles:true}));})()" % t)
                b.pump(0.4)
            b.screenshot(out, [float(v) for v in clip.split(",")] if clip else None)
            print("wrote", out)
        elif mode == "eval":
            src = args[0]
            if os.path.exists(src):
                src = open(src).read()
            wait = float(opt(args, "--wait", "0"))
            print(json.dumps(b.evaluate(src), indent=1))
            if wait:
                b.pump(wait)
        for line in b.console():
            print(line)
    finally:
        b.close()


if __name__ == "__main__":
    main()

