function addChain(s, dir, tb, lip, devBase, sizeBase, spread) {
  const nb = 3 + Math.floor(rng() * 4), sp = rnd(0.028, 0.048), pinch = rnd(0.45, 1.1), drag = rnd(0.45, 0.9);
  for (let j = 0; j < nb; j++) {
    const off = (j - (nb - 1) / 2) * sp;
