function makeSpeckleCanvas() {                     // cluster of micro-droplets
  const S = 128;
  const cv = document.createElement('canvas');     // stays detached, never appended to the DOM
  cv.width = cv.height = S;
  const ctx = cv.getContext('2d');
  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, S, S);
  ctx.globalCompositeOperation = 'lighter';
  for (let i = 0; i < 96; i++) {
    const ang = rnd(0, TAU), rr = Math.min(S * 0.45, S * 0.17 * Math.sqrt(-2 * Math.log(1 - 0.985 * rng())));
    const x = S / 2 + rr * Math.cos(ang), y = S / 2 + rr * Math.sin(ang);
    const rad = 1.3 + 3.2 * rng() * rng(), b = 0.35 + 0.65 * rng();
    const g = ctx.createRadialGradient(x, y, 0, x, y, rad);
    g.addColorStop(0, 'rgba(255,255,255,' + b.toFixed(3) + ')');
    g.addColorStop(0.5, 'rgba(255,255,255,' + (b * 0.45).toFixed(3) + ')');
    g.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(x, y, rad, 0, TAU);
    ctx.fill();
  }
  return cv;
}
