function makeFxCanvas() {                          // R: cluster of micro-droplets, G: wispy vapor noise
  const S = 128;
  const cv = document.createElement('canvas');     // stays detached, never appended to the DOM
  cv.width = cv.height = S;
  const ctx = cv.getContext('2d');
  const img = ctx.createImageData(S, S), d = img.data;
  const octs = [4, 8, 16, 32];
  const grids = octs.map(function (m) {            // seeded, tileable value-noise lattices
    const g = new Float32Array(m * m);
    for (let i = 0; i < m * m; i++) g[i] = rng();
    return g;
  });
  for (let y = 0; y < S; y++) for (let x = 0; x < S; x++) {
    let v = 0, amp = 0.5, tot = 0;
    for (let o = 0; o < octs.length; o++) {
      const m = octs[o], fx = x / S * m, fy = y / S * m;
      const x0 = Math.floor(fx), y0 = Math.floor(fy), tx = fx - x0, ty = fy - y0;
      const sx = tx * tx * (3 - 2 * tx), sy = ty * ty * (3 - 2 * ty);
      const g = grids[o], x1 = (x0 + 1) % m, y1 = (y0 + 1) % m;
      v += amp * lerp(lerp(g[y0 * m + x0], g[y0 * m + x1], sx), lerp(g[y1 * m + x0], g[y1 * m + x1], sx), sy);
      tot += amp;
      amp *= 0.5;
    }
    const o = (y * S + x) * 4;
    d[o] = 0; d[o + 1] = 255 * clamp(v / tot, 0, 1); d[o + 2] = 0; d[o + 3] = 255;
  }
  ctx.putImageData(img, 0, 0);
  ctx.globalCompositeOperation = 'lighter';
  for (let i = 0; i < 22; i++) {
    const ang = rnd(0, TAU), rr = Math.min(S * 0.40, S * 0.20 * Math.sqrt(-2 * Math.log(1 - 0.97 * rng())));
    const x = S / 2 + rr * Math.cos(ang), y = S / 2 + rr * Math.sin(ang);
    const rad = 3.5 + 6.0 * rng() * rng(), b = 0.45 + 0.55 * rng();
    const g = ctx.createRadialGradient(x, y, 0, x, y, rad);
    g.addColorStop(0, 'rgba(255,0,0,' + b.toFixed(3) + ')');
    g.addColorStop(0.55, 'rgba(255,0,0,' + (b * 0.6).toFixed(3) + ')');
    g.addColorStop(1, 'rgba(255,0,0,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(x, y, rad, 0, TAU);
    ctx.fill();
  }
  return cv;
}
const dropTex = new THREE.CanvasTexture(makeDropletCanvas());
const fxTex = new THREE.CanvasTexture(makeFxCanvas());
fxTex.wrapS = fxTex.wrapT = THREE.RepeatWrapping;

