const cy = 0.050 * Math.pow(clamp(-nx * 1.2 + ny * 0.25 - 0.12, 0, 1), 2.2) * band;
const mg = 0.050 * Math.pow(clamp(nx * 1.2 + ny * 0.10 - 0.12, 0, 1), 2.2) * band;
return [out[0] + amb + caus, out[2] + amb + cy, out[3] + amb + mg];

