(async () => {
  const $ = (id) => document.getElementById(id);
  const cd = $('countdown'), sc = $('scrubber'), tg = $('btn-toggle'), rf = $('btn-refire');
  const ip = $('icon-pause'), ipl = $('icon-play');
  const pills = [...document.querySelectorAll('.speed-pill')];
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const vis = (el) => getComputedStyle(el).display !== 'none';
  const snap = () => ({ t: performance.now(), cdText: cd.textContent, cdDisp: getComputedStyle(cd).display,
    v: parseFloat(sc.value), raw: sc.value, aria: tg.getAttribute('aria-label'), pause: vis(ip), play: vis(ipl) });
  const out = [];
  const ok = (name, cond, info) => out.push((cond ? 'PASS ' : 'FAIL ') + name + (info !== undefined ? '  [' + info + ']' : ''));

  // ---- 1. initial countdown: observe digit transitions + hide + playback to the end
  const log = [];
  const t0 = performance.now();
  let last = null;
  while (performance.now() - t0 < 13500) {
    const s = snap();
    const key = s.cdText + '|' + s.cdDisp + '|' + s.aria + '|' + (s.v > 0) + '|' + (s.v >= 8);
    if (key !== last) { log.push(s); last = key; }
    await sleep(4);
  }
  const find = (pred) => log.find(pred);
  const e3 = log[0];
  const e2 = find((s) => s.cdText === '2'), e1 = find((s) => s.cdText === '1');
  const eh = find((s) => s.cdDisp === 'none'), eEnd = find((s) => s.v >= 8);
  ok('countdown starts at "3" visible, scrubber 0, pause icon', e3.cdText === '3' && e3.cdDisp === 'block' && e3.raw === '0' && e3.pause && !e3.play && e3.aria === 'Pause', JSON.stringify(e3));
  ok('"2" then "1" one second apart', e2 && e1 && Math.abs((e1.t - e2.t) - 1000) < 40, e2 && e1 ? (e1.t - e2.t).toFixed(1) : 'missing');
  ok('hidden 1 s after "1" (text empty, display none)', eh && e1 && Math.abs((eh.t - e1.t) - 1000) < 40 && eh.cdText === '', eh && e1 ? (eh.t - e1.t).toFixed(1) : 'missing');
  ok('scrubber stays 0 during countdown', log.filter((s) => s.cdDisp === 'block').every((s) => s.raw === '0'));
  ok('reaches 8.000 exactly 8 s after countdown ends (1.0x)', eEnd && eh && Math.abs((eEnd.t - eh.t) - 8000) < 60, eEnd && eh ? (eEnd.t - eh.t).toFixed(1) : 'missing');
  let s = snap();
  ok('ENDED: scrubber max, play icon, aria Play', s.v === 8 && s.play && !s.pause && s.aria === 'Play', JSON.stringify(s));

  // ---- 2. toggle from ENDED -> PLAYING from 0
  tg.click(); await sleep(250); s = snap();
  ok('ENDED->PLAYING restarts from 0', s.v > 0.1 && s.v < 0.5 && s.pause && s.aria === 'Pause' && s.cdDisp === 'none', JSON.stringify(s));
  // ---- 3. PLAYING -> PAUSED
  tg.click(); await sleep(60); const p1 = snap(); await sleep(300); const p2 = snap();
  ok('PAUSED freezes simTime, play icon', p1.v === p2.v && p2.play && !p2.pause && p2.aria === 'Play', p1.raw + ' / ' + p2.raw);
  // ---- 4. speed pill 2.0x
  pills[3].click();
  ok('speed pill exclusive state', pills.map((p) => p.classList.contains('is-active') + ':' + p.getAttribute('aria-checked')).join(',') === 'false:false,false:false,false:false,true:true');
  // ---- 5. PAUSED -> PLAYING at 2x
  tg.click(); await sleep(50); const a1 = snap(); await sleep(500); const a2 = snap();
  const rate = (a2.v - a1.v) / ((a2.t - a1.t) / 1000);
  ok('PLAYING at 2.0x', Math.abs(rate - 2.0) < 0.12 && a2.pause && a2.aria === 'Pause', rate.toFixed(3));
  // ---- 6. scrub -> PAUSED
  sc.value = '5.25'; sc.dispatchEvent(new Event('input', { bubbles: true })); await sleep(200); s = snap();
  ok('scrub pauses at value', s.v === 5.25 && s.play && s.aria === 'Play' && s.cdDisp === 'none', JSON.stringify(s));
  // ---- 7. refire: hold 1 s silently then play at persisted 2x
  rf.click(); const r0 = snap();
  ok('refire resets immediately', r0.raw === '0' && r0.pause && !r0.play && r0.aria === 'Pause' && r0.cdDisp === 'none' && r0.cdText === '', JSON.stringify(r0));
  const hold = []; const th = performance.now();
  while (performance.now() - th < 1700) { hold.push(snap()); await sleep(4); }
  const firstMove = hold.find((h) => h.v > 0);
  ok('REFIRE_HOLD lasts 1.000 s, countdown hidden throughout', firstMove && Math.abs((firstMove.t - r0.t) - 1000) < 45 && hold.every((h) => h.cdDisp === 'none'), firstMove ? (firstMove.t - r0.t).toFixed(1) : 'none');
  const lastH = hold[hold.length - 1];
  const rate2 = (lastH.v - firstMove.v) / ((lastH.t - firstMove.t) / 1000);
  ok('speed persists across refire (2.0x)', Math.abs(rate2 - 2.0) < 0.12, rate2.toFixed(3));
  // ---- 8. refire then toggle during hold -> PAUSED at 0
  rf.click(); await sleep(300); tg.click(); await sleep(1300); s = snap();
  ok('toggle during REFIRE_HOLD -> PAUSED at 0', s.raw === '0' && s.play && s.aria === 'Play' && s.cdDisp === 'none', JSON.stringify(s));
  // ---- 9. scrub during hold
  rf.click(); await sleep(200); sc.value = '2.5'; sc.dispatchEvent(new Event('input', { bubbles: true })); await sleep(1200); s = snap();
  ok('scrub during REFIRE_HOLD cancels hold', s.v === 2.5 && s.play && s.aria === 'Play', JSON.stringify(s));
  // ---- 10. pills 0.25
  pills[0].click(); tg.click(); await sleep(50); const b1 = snap(); await sleep(600); const b2 = snap();
  const rate3 = (b2.v - b1.v) / ((b2.t - b1.t) / 1000);
  ok('PLAYING at 0.25x', Math.abs(rate3 - 0.25) < 0.03, rate3.toFixed(3));
  // ---- 11. DOM contract
  const bodyKids = [...document.body.children].map((e) => e.tagName + (e.id ? '#' + e.id : ''));
  ok('body children', bodyKids.join(',') === 'CANVAS#stage,DIV#countdown,DIV#dock,SCRIPT,SCRIPT', bodyKids.join(','));
  const dock = $('dock').getBoundingClientRect();
  ok('dock geometry 536x44 @ bottom 24', Math.round(dock.width) === 536 && Math.round(dock.height) === 44 && Math.round(innerHeight - dock.bottom) === 24, [dock.width, dock.height, innerHeight - dock.bottom].join(' '));
  ok('no extra canvases in DOM', document.querySelectorAll('canvas').length === 1);
  return out.join('\n');
})()

