(async () => {
  // Run early (during the initial COUNTDOWN). MODE is substituted by the caller: 'toggle' | 'scrub' | 'refire'
  const MODE = '__MODE__';
  const $ = (id) => document.getElementById(id);
  const cd = $('countdown'), sc = $('scrubber'), tg = $('btn-toggle'), rf = $('btn-refire');
  const ip = $('icon-pause'), ipl = $('icon-play');
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const vis = (el) => getComputedStyle(el).display !== 'none';
  const snap = () => ({ t: performance.now(), cdText: cd.textContent, cdDisp: getComputedStyle(cd).display,
    v: parseFloat(sc.value), raw: sc.value, aria: tg.getAttribute('aria-label'), pause: vis(ip), play: vis(ipl) });
  const out = [];
  const ok = (name, cond, info) => out.push((cond ? 'PASS ' : 'FAIL ') + name + (info !== undefined ? '  [' + info + ']' : ''));
  // wait until the countdown is genuinely running (digit "2" is only ever set by the state machine)
  const tw = performance.now();
  while (cd.textContent !== '2' && performance.now() - tw < 6000) await sleep(5);
  let s = snap();
  ok('in COUNTDOWN at "2"', s.cdText === '2' && s.cdDisp === 'block' && s.raw === '0', JSON.stringify(s));
  if (MODE === 'toggle') {
    tg.click(); s = snap();
    ok('toggle cancels countdown -> PAUSED at 0', s.cdDisp === 'none' && s.raw === '0' && s.play && !s.pause && s.aria === 'Play', JSON.stringify(s));
    await sleep(2500); s = snap();
    ok('stays paused at 0 (no auto start)', s.raw === '0' && s.cdDisp === 'none' && s.aria === 'Play', JSON.stringify(s));
    tg.click(); await sleep(400); s = snap();
    ok('PAUSED -> PLAYING from 0', s.v > 0.25 && s.v < 0.55 && s.pause && s.aria === 'Pause', JSON.stringify(s));
  } else if (MODE === 'scrub') {
    sc.value = '3.3'; sc.dispatchEvent(new Event('input', { bubbles: true })); s = snap();
    ok('scrub cancels countdown -> PAUSED at 3.3', s.cdDisp === 'none' && s.v === 3.3 && s.play && s.aria === 'Play', JSON.stringify(s));
    await sleep(2500); s = snap();
    ok('remains PAUSED at 3.3', s.v === 3.3 && s.cdDisp === 'none', JSON.stringify(s));
    tg.click(); await sleep(300); s = snap();
    ok('resumes from 3.3', s.v > 3.5 && s.v < 3.75 && s.aria === 'Pause', JSON.stringify(s));
  } else {
    rf.click(); const r0 = snap();
    ok('refire during countdown hides it, holds at 0', r0.cdDisp === 'none' && r0.cdText === '' && r0.raw === '0' && r0.pause && r0.aria === 'Pause', JSON.stringify(r0));
    let first = null; const hold = [];
    while (performance.now() - r0.t < 1500) { const h = snap(); hold.push(h); if (!first && h.v > 0) first = h; await sleep(4); }
    ok('plays 1.000 s later, countdown never reappears', first && Math.abs(first.t - r0.t - 1000) < 45 && hold.every((h) => h.cdDisp === 'none'), first ? (first.t - r0.t).toFixed(1) : 'none');
  }
  return out.join('\n');
})()

