(async () => {
  const stage = document.getElementById('stage'), sc = document.getElementById('scrubber');
  const rf = document.getElementById('btn-refire'), tg = document.getElementById('btn-toggle');
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const hash = (str) => { let h = 2166136261 >>> 0; for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 16777619) >>> 0; } return h.toString(16); };
  const grab = (t) => {
    sc.value = String(t);
    sc.dispatchEvent(new Event('input', { bubbles: true }));
    return hash(stage.toDataURL('image/png'));
  };
  const times = [0, 0.5, 1.148, 1.3, 2.0, 3.1, 3.9, 4.7, 5.6, 6.5, 7.3, 8];
  const forward = times.map(grab);
  const backward = times.slice().reverse().map(grab).reverse();
  const shuffled = [5, 0, 9, 3, 11, 1, 7, 2, 10, 4, 8, 6].map((i) => [i, grab(times[i])]);
  const out = [];
  out.push('forward == backward : ' + (forward.join() === backward.join()));
  out.push('forward == shuffled : ' + shuffled.every(([i, h]) => h === forward[i]));
  out.push('all distinct frames : ' + (new Set(forward).size === forward.length));
  // after a re-fire, the resting frame must be identical to the very first one
  rf.click();
  const afterRefire = hash(stage.toDataURL('image/png'));
  out.push('refire frame == t0  : ' + (afterRefire === forward[0]));
  // play for a while, pause, and compare against a scrubbed render of the same simTime
  await sleep(1900); tg.click(); await sleep(80);
  const tPaused = sc.value;
  const live = hash(stage.toDataURL('image/png'));          // (drawing buffer may be cleared -> compare via re-render below)
  const again = grab(tPaused);
  await sleep(50);
  const again2 = grab(tPaused);
  out.push('paused@' + tPaused + ' re-render stable : ' + (again === again2));
  out.push('blank check (t=0 hash differs from empty canvas): ' + (forward[0] !== hash(document.createElement('canvas').toDataURL('image/png'))));
  return out.join('\n');
})()

