// Same studio, but the key / fill boxes are looked up along dA and the rim strips along dB
// (lets a surface keep a clean window reflection while its micro-roughness sparkles in the rims)
vec3 studioEnvSplit(vec3 dA, vec3 dB, float roughA, float roughB) {
  vec3 c = vec3(0.0);
  for (int i = 0; i < 4; i++) {
    vec3 d = i < 2 ? dA : dB;
    float rough = i < 2 ? roughA : roughB;
    float soft = uLSoft[i] + 1.5 * rough;
    float f = dot(d, uLDir[i]);
    vec2 g = vec2(dot(d, uLRgt[i]), dot(d, uLUp[i])) / max(f, 0.001);
    vec2 e = abs(g) - uLSize[i];
    float m = (1.0 - smoothstep(-soft, soft, e.x)) * (1.0 - smoothstep(-soft, soft, e.y)) * step(0.001, f);
    vec2 gn = g / uLSize[i];
    m *= 1.0 - 0.45 * sat(dot(gn, gn) * 0.5);
    c += uLCol[i] * (m / (1.0 + 5.0 * rough));
  }
  return c;
}
vec3 studioAmb(vec3 d) { return mix(uAmbBot, uAmbTop, 0.5 + 0.5 * d.y); }

