input.content:
(async () => {
  const sc = document.getElementById('scrubber'), cd = document.getElementById('countdown');
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  while (getComputedStyle(cd).display !== 'none') await sleep(10);
  const buckets = {};
  let last = null, done = false;
  await new Promise((resolve) => {
    function tick(ts) {
      const v = parseFloat(sc.value);
      if (last !== null) {
        const b = Math.min(7, Math.floor(v));
        (buckets[b] = buckets[b] || []).push(ts - last);
      }
      last = ts;
      if (v >= 8) return resolve();
      requestAnimationFrame(tick);
    }
    requestAnimationFrame(tick);
  });
  const out = [];
  const gl = document.getElementById('stage').getContext('webgl2') || document.getElementById('stage').getContext('webgl');
  const dbg = gl && gl.getExtension('WEBGL_debug_renderer_info');
  out.push('renderer: ' + (dbg ? gl.getParameter(dbg.UNMASKED_RENDERER_WEBGL) : 'n/a') + '  buffer ' + gl.drawingBufferWidth + 'x' + gl.drawingBufferHeight);
  for (const b of Object.keys(buckets)) {
    const a = buckets[b], avg = a.reduce((x, y) => x + y, 0) / a.length, mx = Math.max(...a);
    out.push('sim ' + b + '-' + (+b + 1) + 's: frames ' + a.length + '  avg ' + avg.toFixed(2) + ' ms  max ' + mx.toFixed(1) + ' ms');
  }
  return out.join('\n');
})()

