(async () => {
  const stage = document.getElementById('stage'), sc = document.getElementById('scrubber');
  const gl = stage.getContext('webgl2') || stage.getContext('webgl');
  const px = new Uint8Array(4);
  const render = (t) => {
    sc.value = String(t);
    sc.dispatchEvent(new Event('input', { bubbles: true }));
    gl.readPixels(0, 0, 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, px);   // force the pipeline to finish
  };
  const out = [];
  for (const t of [0.5, 1.1, 1.35, 2.0, 3.0, 3.9, 4.6, 5.4, 6.2, 7.0, 7.8]) {
    render(t);
    const t0 = performance.now();
    const N = 3;
    for (let i = 0; i < N; i++) render(t + i * 0.001);
    out.push('t=' + t.toFixed(2) + '  ' + ((performance.now() - t0) / N).toFixed(1) + ' ms/frame');
  }
  return out.join('\n');
})()

