}

/* ==========================================================================
 * 6. GLSL
 * ======================================================================== */
const glf = function (v) { return (Math.round(v * 1e6) / 1e6).toFixed(6); };
function glslDefines() {
  const D = {
    X_E: X_E, R_BUL: R_BUL, NOSE_L: NOSE_L, BULLET_L: BULLET_L, BT_S: BT_S, CAN_S: CAN_S,
    T_PUNCT: T_PUNCT, T_CAV: T_CAV, T_EXIT: T_EXIT, T_BW: T_BW, D_A: D_A, B_Q: B_Q, C_Q: C_Q,
    DIMPLE_W: DIMPLE_W, DIMPLE_D: DIMPLE_D, BULGE: BULGE, BULGE_W: BULGE_W, K_CAV: K_CAV, GROW2: GROW2,
    LIP_E: LIP_E, TAU_LE: TAU_LE, LIPE_W: LIPE_W, LIP_X: LIP_X, TAU_LX: TAU_LX, LIPX_W: LIPX_W,
    T_BURST: T_BURST, TAU_BURST: TAU_BURST, E_MAX: E_MAX, R_REF: R_REF, BURST_AX: BURST_AX, DRIFT: DRIFT,
    T_GRAV: T_GRAV, TAU_GRAV: TAU_GRAV, G_ACC: G_ACC, T_BRK0: T_BRK0, T_BRK1: T_BRK1,
    TEAR_KH: TEAR_KH, ARC_I: ARC_I, SKIN_SPEED: SKIN_SPEED, DT_VEL: DT_VEL,
    Y_BOT: Y_BOT, BODY_H: BODY_H, DROP_K: DROP_K,
    WATER_REFL: WATER_REFL, WATER_TRANS: WATER_TRANS, SKIN_GAIN: SKIN_GAIN, BULLET_GAIN: BULLET_GAIN, TUBE_GAIN: TUBE_GAIN
  };
  return Object.keys(D).map(function (k) { return '#define ' + k + ' ' + glf(D[k]); }).join('\n') + '\n';
}

const GLSL_UTIL = `
  float sat(float x) { return clamp(x, 0.0, 1.0); }
  float hash13(vec3 p) {
    p = fract(p * 0.1031);
    p += dot(p, p.zyx + 31.32);
    return fract((p.x + p.y) * p.z);
  }
  float vnoise(vec3 p) {
    vec3 i = floor(p);
    vec3 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash13(i);
    float b = hash13(i + vec3(1.0, 0.0, 0.0));
    float c = hash13(i + vec3(0.0, 1.0, 0.0));
    float d = hash13(i + vec3(1.0, 1.0, 0.0));
    float e = hash13(i + vec3(0.0, 0.0, 1.0));
    float g = hash13(i + vec3(1.0, 0.0, 1.0));
    float h = hash13(i + vec3(0.0, 1.0, 1.0));
    float k = hash13(i + vec3(1.0, 1.0, 1.0));
    return mix(mix(mix(a, b, f.x), mix(c, d, f.x), f.y), mix(mix(e, g, f.x), mix(h, k, f.x), f.y), f.z);
  }
  float sn(vec3 p) {
    return sin(p.x + 1.7 * sin(p.y * 0.6)) * sin(p.y + 1.3 * sin(p.z * 0.7)) * sin(p.z + 1.9 * sin(p.x * 0.5));
  }
  vec3 swirl(vec3 p) {                   // smooth pseudo-random vector field in [-1, 1]
    return vec3(sin(p.y * 1.7 + 1.3 * sin(p.z * 1.1 + p.x * 0.7)),
                sin(p.z * 1.9 + 1.3 * sin(p.x * 1.3 + p.y * 0.6)),
                sin(p.x * 1.6 + 1.3 * sin(p.y * 1.2 + p.z * 0.8)));
  }
`;

// Rayleigh-Taylor speed field + sheet rupture time (mirrors breakTimeJS)
const GLSL_FIELD = `
  float burstS(vec3 q) {
    return 1.0 + 0.42 * sn(q * 4.3 + vec3(0.3, 1.1, 2.4)) + 0.22 * sn(q.zxy * 8.7 + vec3(1.7, 0.2, 0.9));
  }
  float breakTime(vec3 q) {
    float rho2 = dot(q.yz, q.yz);
    float wE = exp(-((q.x - X_E) * (q.x - X_E) + rho2) / (LIPE_W * LIPE_W));
    float wX = exp(-((q.x + X_E) * (q.x + X_E) + rho2) / (LIPX_W * LIPX_W));
    float n1 = 0.5 + 0.5 * sn(q * 3.1 + vec3(4.2, 0.7, 1.9));
    float n2 = 0.5 + 0.5 * sn(q.yzx * 6.9 + vec3(0.4, 2.2, 5.1));
    float tb = T_BRK0 + T_BRK1 * (0.62 * n1 + 0.38 * n2);
    tb = mix(tb, T_CAV + 0.60 + 1.5 * (1.0 - wE), smoothstep(0.06, 0.55, wE));
    tb = mix(tb, T_EXIT + 0.35 + 1.2 * (1.0 - wX), smoothstep(0.06, 0.55, wX));
    return tb;
  }
`;

/* The fluid deformation field. q is a rest-space point of the water mass and
 * T = (simTime, bulletTipX, gravityFall, dimple). The same function moves the
 * water surface, the latex (before it tears away), the vapor tunnel wall and
 * every tracer droplet, so all of them stay glued together by construction. */

