528	  /* The fluid deformation field. q is a rest-space point of the water mass and
529	   * T = (simTime, bulletTipX, gravityFall, dimple). The same function moves the
530	   * water surface, the latex (before it tears away), the vapor tunnel wall and
531	   * every tracer droplet, so all of them stay glued together by construction. */
532	  const GLSL_DEFORM = `
533	    uniform vec4 uT0;
534	    uniform vec4 uT1;
535	
536	    float noseR(float s) {
537	      s = clamp(s, 0.0, 1.0);
538	      return 0.4 * s + 0.6 * pow(sin(1.5707963 * s) + 1e-5, 0.85);
539	    }
540	    float tPass(float x) {                 // cavitation clock: when did the tip pass station x
541	      float dd = max((X_E - x) - D_A, 0.0);
542	      float s = (-B_Q + sqrt(B_Q * B_Q + 4.0 * C_Q * dd)) / (2.0 * C_Q);
543	      return T_CAV + T_BW * s;
544	    }
545	    float burstE(float t) {
546	      float k = 1.0 - exp(-max(t - T_BURST, 0.0) / TAU_BURST);
547	      return E_MAX * k * k;
548	    }
549	    float fallOf(float t) {
550	      float u = max(t - T_GRAV, 0.0);
551	      return G_ACC * (0.5 * u * u - TAU_GRAV * u + TAU_GRAV * TAU_GRAV * (1.0 - exp(-u / TAU_GRAV)));
552	    }
553	    float fallVel(float t) {
554	      float u = max(t - T_GRAV, 0.0);
555	      return G_ACC * (u - TAU_GRAV * (1.0 - exp(-u / TAU_GRAV)));
556	    }
557	
558	    vec3 deform(vec3 q, float lipK, vec4 T) {
559	      float t = T.x;
560	      float rho2 = dot(q.yz, q.yz);
561	      float rho = sqrt(rho2);
562	      vec2 er = q.yz / max(rho, 1e-6);
563	      float th = atan(q.z, q.y);
564	      float dE2 = (q.x - X_E) * (q.x - X_E) + rho2;
565	      float dX2 = (q.x + X_E) * (q.x + X_E) + rho2;
566	
567	      // (1) elastic dimple under the tip, water pushed ahead of the tip before exit
568	      //     (the dimple is a crease elongated along the line of sight, so the lateral
569	      //      camera sees the nose sitting in a clean V-notch of the silhouette)
570	      float dq2 = ((q.x - X_E) * (q.x - X_E) + q.y * q.y) / (DIMPLE_W * DIMPLE_W) + q.z * q.z / (DIMPLE_D * DIMPLE_D);
571	      float x1 = q.x - T.w / pow(1.0 + dq2, 0.9)
572	                     - BULGE * smoothstep(T_EXIT - 0.60, T_EXIT - 0.02, t) * exp(-dX2 / (BULGE_W * BULGE_W));
573	
574	      // (2) cavity: the hole hugs the bullet, then the low-pressure vapor tunnel grows
575	      //     behind it. Incompressible radial push: rho' = sqrt(rho^2 + Rc^2).
576	      float b = x1 - T.y;
577	      float hug = step(0.0, b) * 1.10 * R_BUL * noseR(b / NOSE_L) * smoothstep(T_PUNCT, T_PUNCT + 0.05, t);
578	      float tau = max(t - tPass(x1), 0.0);
579	      float rgh = 1.0 + 0.24 * sin(q.x * 17.0 + 2.0 * sin(th * 3.0 + q.x * 5.0) + t * 1.3) * sin(th * 5.0 + q.x * 7.0 + 1.3);
580	      float rc2 = hug * hug + 2.0 * K_CAV * tau * (1.0 + GROW2 * tau) * rgh;
581	      float rho1 = sqrt(rho2 + rc2);
582	
583	      // (3) crown sheets: backward splash at the entry hole, forward cone at the exit hole
584	      float fE = 0.72 + 0.20 * sin(7.0 * th + 0.8) + 0.16 * sin(13.0 * th + 2.9) + 0.10 * sin(23.0 * th + 5.1);
585	      float aE = lipK * LIP_E * (1.0 - exp(-max(t - T_CAV, 0.0) / TAU_LE)) * exp(-dE2 / (LIPE_W * LIPE_W)) * fE;
586	      x1 += aE * 0.80;
587	      rho1 += aE * 0.60;
588	      float fX = 0.75 + 0.18 * sin(9.0 * th + 1.9) + 0.15 * sin(17.0 * th + 0.4) + 0.10 * sin(29.0 * th + 3.3);
589	      float aX = lipK * LIP_X * (1.0 - exp(-max(t - T_EXIT, 0.0) / TAU_LX)) * exp(-dX2 / (LIPX_W * LIPX_W)) * fX;
590	      x1 -= aX * 0.92;
591	      rho1 += aX * 0.39;
592	
593	      vec3 p = vec3(x1, er * rho1);
594	
595	      // (4) burst: homologous expansion modulated by the Rayleigh-Taylor finger field
596	      float e = burstE(t);
597	      float att = 1.0 / (1.0 + 0.35 * rho2 / (R_REF * R_REF));
598	      p += vec3(q.x * BURST_AX, q.y, q.z) * (burstS(q) * e * att / R_REF);
599	      p.x -= DRIFT * e;
600	
601	      // (5) global free-fall frame
602	      p.y -= T.z;
603	      return p;
604	    }
605	  `;
