607	  const GLSL_ENV = `
608	    uniform vec3 uLDir[4];
609	    uniform vec3 uLRgt[4];
610	    uniform vec3 uLUp[4];
611	    uniform vec3 uLCol[4];
612	    uniform vec2 uLSize[4];
613	    uniform float uLSoft[4];
614	    uniform vec2 uBoxScale;
615	    uniform vec3 uAmbTop;
616	    uniform vec3 uAmbBot;
617	    uniform float uExposure;
618	
619	    // Analytic studio: four rectangular soft-boxes (key, fill, two rim strips)
620	    vec3 studioEnv(vec3 d, float rough) {
621	      vec3 c = vec3(0.0);
622	      for (int i = 0; i < 4; i++) {
623	        float soft = uLSoft[i] + 1.5 * rough;
624	        float f = dot(d, uLDir[i]);
625	        vec2 g = vec2(dot(d, uLRgt[i]), dot(d, uLUp[i])) / max(f, 0.001);
626	        vec2 e = abs(g) - uLSize[i] * uBoxScale;
627	        float m = (1.0 - smoothstep(-soft, soft, e.x)) * (1.0 - smoothstep(-soft, soft, e.y)) * step(0.001, f);
628	        vec2 gn = g / (uLSize[i] * uBoxScale);
629	        m *= 1.0 - 0.45 * sat(dot(gn, gn) * 0.5);            // diffuser hot-spot falloff
630	        c += uLCol[i] * (m / (1.0 + 5.0 * rough));
631	      }
632	      return c;
633	    }
634	    // Same studio, but the key / fill boxes are looked up along dA and the rim strips along dB
635	    // (lets a surface keep a clean window reflection while its micro-roughness sparkles in the rims)
