  void main() {
    vec3 q = position;
    vec3 n = normalize(normal);
    vec3 hlp = abs(n.x) > 0.8 ? vec3(0.0, 1.0, 0.0) : vec3(1.0, 0.0, 0.0);
    vec3 t1 = normalize(cross(hlp, n));
    vec3 t2 = cross(n, t1);
    float eps = min(0.012, 0.12 * length(q.yz));
    vec3 p0 = surf(q, n, uT0);
    vec3 p1 = surf(q + t1 * eps, n, uT0);
    vec3 p2 = surf(q + t2 * eps, n, uT0);
    vec3 nn = cross(p1 - p0, p2 - p0);
    float l = length(nn);
    vNrm = l > 1e-12 ? nn / l : n;
    vRest = q;
    vWorld = p0;
    vNr = n;
    vInfo = surfInfo(q, p0);
    gl_Position = projectionMatrix * viewMatrix * vec4(p0, 1.0);
  }
`;
