const BODY_FS = `
  uniform vec4 uT0;
  uniform float uSide;
  varying vec3 vRest;
  varying vec3 vWorld;
  varying vec3 vNrm;
  varying vec3 vInfo;
  void main() {
    float t = uT0.x;
    // Sheet rupture: holes nucleate where the film is thinnest and spread
    float fine = (vnoise(vRest * 8.0) - 0.5) * 0.34 + (vnoise(vRest * 19.0) - 0.5) * 0.08;
    float hole = vInfo.x + fine - t;
    if (hole < 0.0) discard;

    vec3 N0 = normalize(vNrm) * uSide;
    vec3 V = normalize(cameraPosition - vWorld);
    float nv0 = dot(N0, V);
    if (nv0 < 0.03) N0 = normalize(N0 + V * (0.03 - nv0));
    // "frosted" capillary roughness left behind by the retracting latex
    float ex = t - vInfo.y;
    float frost = smoothstep(0.0, 0.05, ex) * (0.20 + 0.80 * exp(-max(ex, 0.0) / 0.9));
    vec3 N = normalize(N0 + (swirl(vRest * 38.0) * 0.6 + swirl(vRest * 91.0 + 3.0) * 0.4) * (0.010 + 0.085 * frost));
    float nv = dot(N, V);
    if (nv < 0.03) N = normalize(N + V * (0.03 - nv));
    nv = sat(dot(N, V));

    float F = 0.02 + 0.98 * pow(1.0 - nv, 5.0);
    vec3 I = -V;
    vec3 R = reflect(I, N);
    float rgh = 0.012 + 0.035 * frost;
    // clean (slightly blurred) window reflection of the key box, sparkling rim strips
    vec3 refl = studioEnvSplit(reflect(I, N0), R, 0.02 + 0.10 * frost, rgh) * WATER_REFL + studioAmb(R) * 4.0;
    // ball-lens transmission: refract in, cross the mass, refract out (inverted rim glints)
    vec3 T1 = refract(I, N, 0.752);
    vec3 N2 = normalize(N + T1 * (-2.0 * dot(T1, N)));
    vec3 T2 = refract(T1, -N2, 1.33);
    if (dot(T2, T2) < 0.25) T2 = reflect(T1, -N2);
    vec3 trans = studioEnv(T2, rgh + 0.08) * WATER_TRANS * vec3(0.86, 0.96, 1.0);
    // rim light scattered through the limb: cyan on its side, magenta on the other
    vec3 glow = vec3(0.0);
    for (int i = 2; i < 4; i++) {
      float w = sat(dot(N, uLDir[i]) * 0.5 + 0.5);
      glow += uLCol[i] * w * w;
    }
    float limb = pow(1.0 - nv, 2.5);
    // internal caustic: key light focused onto the far side of the mass
    float caus = pow(sat(dot(N.xy, -normalize(uLDir[0].xy))), 2.0) * pow(1.0 - nv, 1.2);
    vec3 col = refl * F + trans * (1.0 - F) * (1.0 - F) + glow * limb * 0.42 + uLCol[0] * caus * 0.30;
    col += vec3(0.014, 0.036, 0.054) * (0.7 + 1.3 * (1.0 - nv)) + studioDiffuse(N, 0.6) * frost * 0.030;
    float rim = 1.0 - smoothstep(0.0, 0.05, hole);          // thickened rim of each opening hole
    col += (glow * 0.05 + vec3(0.012, 0.024, 0.030)) * rim;
    float alpha = 0.15 + 0.50 * limb + 0.5 * F + lum(col) * 0.9 + rim * 0.12 + frost * 0.08;
    alpha *= smoothstep(0.0, 0.016, hole);
    if (uSide < 0.0) { col *= 0.55; alpha *= 0.55; }
    gl_FragColor = outColor(col, alpha);
  }
`;

const TUBE_FS = `
  uniform vec4 uT0;
