const bodyGeo = (function () {
  const NA = 150, rows = NA + 1, count = rows * NT;
  const pos = new Float32Array(count * 3), nor = new Float32Array(count * 3), tm = new Float32Array(count);
  for (let j = 0; j < rows; j++) {
    const al = A_MIN + (Math.PI - 2 * A_MIN) * j / NA, ca = Math.cos(al), sa = Math.sin(al);
    for (let k = 0; k < NT; k++) {
      const th = TAU * k / NT, dx = ca, dy = sa * Math.cos(th), dz = sa * Math.sin(th);
      const s = surfaceDist(dx, dy, dz), i = j * NT + k;
      const x = dx * s, y = dy * s, z = dz * s, n = bodyNormalAt(x, y, z);
      pos[i * 3] = x; pos[i * 3 + 1] = y; pos[i * 3 + 2] = z;
      nor[i * 3] = n[0]; nor[i * 3 + 1] = n[1]; nor[i * 3 + 2] = n[2];
      tm[i] = tearMetric(x, y, z);
    }
  }
  const idx = new Uint16Array(NA * NT * 6);
  let p = 0;
  for (let j = 0; j < NA; j++) for (let k = 0; k < NT; k++) {
