(async () => {
  // Requires a debug copy of the page exposing window.__dbg (never part of the deliverable).
  const D = window.__dbg;
  const stage = document.getElementById('stage'), sc = document.getElementById('scrubber');
  const gl = D.renderer.getContext();
  const px = new Uint8Array(4);
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const draw = () => { D.renderer.render(D.scene, D.camera); gl.readPixels(0, 0, 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, px); };
  const med = (a) => a.slice().sort((x, y) => x - y)[Math.floor(a.length / 2)];
  const out = [];
  for (const t of [1.35, 3.2, 5.4, 6.4]) {
    sc.value = String(t); sc.dispatchEvent(new Event('input', { bubbles: true }));
    const names = Object.keys(D.parts);
    const base = {}; names.forEach((n) => base[n] = D.parts[n].visible);
    const configs = [['ALL', []], ['none', names]].concat(names.filter((n) => base[n]).map((n) => ['-' + n, [n]]));
    const times = {}; configs.forEach((c) => times[c[0]] = []);
    for (let round = 0; round < 7; round++) {
      for (const [label, off] of configs) {
        names.forEach((n) => D.parts[n].visible = base[n] && !off.includes(n));
        draw();
        const t0 = performance.now(); draw(); times[label].push(performance.now() - t0);
      }
    }
    names.forEach((n) => D.parts[n].visible = base[n]);
    out.push('t=' + t + ': ' + configs.map((c) => c[0] + '=' + med(times[c[0]]).toFixed(0)).join('  '));
    await sleep(10);
  }
  return out.join('\n');
})()

