    if (kE * A.x > 1e-4) {
      kE *= 0.72 + 0.20 * sin(7.0 * th + 0.8) + 0.16 * sin(13.0 * th + 2.9) + 0.10 * sin(23.0 * th + 5.1);
      x1 += kE * A.x * 0.80;
      rho1 += kE * A.x * 0.60;
      vx += kE * uAd.x * 0.80;
      vr += kE * uAd.x * 0.60;
    }
    float kX = lipK * exp(-dX2 / (LIPX_W * LIPX_W));
    if (kX * A.y > 1e-4) {
      kX *= 0.75 + 0.18 * sin(9.0 * th + 1.9) + 0.15 * sin(17.0 * th + 0.4) + 0.10 * sin(29.0 * th + 3.3);
      x1 -= kX * A.y * 0.92;
      rho1 += kX * A.y * 0.39;
      vx -= kX * uAd.y * 0.92;
      vr += kX * uAd.y * 0.39;
    }
    vec3 p = vec3(x1, er * rho1);
    vec3 v = vec3(vx, er * vr);

    // (4) burst: homologous expansion modulated by the Rayleigh-Taylor finger field
    if (A.z > 0.0) {
      vec3 dirv = vec3(q.x * BURST_AX, q.y, q.z) * (burstS(q) / ((1.0 + 0.35 * rho2 / (R_REF * R_REF)) * R_REF));
      p += dirv * A.z;
      p.x -= DRIFT * A.z;
      v += dirv * uAd.z;
      v.x -= DRIFT * uAd.z;
    }

    // (5) global free-fall frame
    p.y -= T.z;
    v.y -= uAd.w;
    vel = v;
    return p;
  }
  vec3 deform(vec3 q, float lipK, vec4 T, vec4 A) {
    vec3 unusedVel;
    return deformPV(q, lipK, T, A, unusedVel);
  }
`;

