const PARTICLE_VS = `
  attribute vec3 aQ;
  attribute vec3 aDev;
  attribute vec4 aTime;
  attribute vec4 aMisc;
  attribute vec4 aAux;
  attribute vec3 aChain;
  uniform float uPxK;
  varying vec2 vUv;
  varying vec2 vAxis;
  varying vec4 vInfo;
  varying float vBoost;

  // Closed-form trajectory. Tracers ride the deforming water (and are released
  // with a drag-limited deviation velocity); free particles are ballistic.
  vec3 particleAt(vec4 T, vec4 A, vec3 q) {
    float t0 = aTime.x;
    float a = max(T.x - t0, 0.0);
    float k = aTime.w;
    float D = (1.0 - exp(-k * a)) / k;
    float gs = aMisc.z;
    vec3 p;
    if (aMisc.y < 3.5) {
      p = deform(q, aAux.x, T, A);
      p.y += (1.0 - gs) * max(T.z - fallOf(t0), 0.0);
    } else {
      p = q;
      p.y -= gs * max(T.z - fallOf(t0) - fallVel(t0) * a, 0.0);
    }
    return p + aDev * D;
  }

  void main() {
    float t = uT0.x;
    float age = t - aTime.x;
    float life = aTime.z;
    float vis = smoothstep(0.0, aTime.y, age) * (1.0 - smoothstep(life * 0.55, life, age));
    if (vis < 0.002) {
      gl_Position = vec4(2.0, 2.0, 2.0, 1.0);
      vUv = vec2(0.0); vAxis = vec2(1.0, 0.0); vInfo = vec4(0.0); vBoost = 1.0;
      return;
    }
    float kind = mod(aMisc.y, 4.0);
    float seed = aMisc.w;
    bool chain = dot(aChain, aChain) > 1e-9;
    float a = max(age, 0.0);
    float Dk = (1.0 - exp(-aTime.w * a)) / aTime.w;
    vec3 P = particleAt(uT0, uA0, aQ);
    // chains: the next bead of the ligament sits one velocity increment further out
    vec3 P2;
    if (chain) P2 = P + aChain * Dk;
    else P2 = particleAt(uT1, uA1, aQ);
    vec4 mv = viewMatrix * vec4(P, 1.0);
    vec4 mv2 = viewMatrix * vec4(P2, 1.0);
    vec2 d = chain ? (mv2.xy - mv.xy) : (mv.xy - mv2.xy);
    float dl = length(d);
    vec2 axis = dl > 1e-6 ? d / dl : vec2(1.0, 0.0);
    float r = aMisc.x * (1.0 + aAux.z * a);
    float halfL;
    float halfW;
    if (kind < 0.5) {
      if (chain) {
        // Plateau-Rayleigh: the stretching ligament necks down between beads and
        // pinches off once the bead spacing exceeds ~pi diameters
        float gap = length(aChain) * Dk;
        float fill = 1.0 - smoothstep(2.6, 5.2, gap / r);
        halfL = r + 0.55 * min(dl, 5.2 * r) * fill;
        halfW = r * mix(1.0, 0.64, fill);
      } else {
        float speed = dl / DT_VEL;
        float st = 1.0 + min(speed * 0.55, 1.8) * exp(-a / 0.45);
        st *= 1.0 + 0.20 * exp(-a / 0.9) * sin(a * (7.0 + 5.0 * seed) + seed * 40.0);   // shape oscillation
        halfL = r * st;
        halfW = r / sqrt(st);
      }
    } else {
      float st = 1.0 + min(dl / DT_VEL * 0.25, 1.2);
      halfL = r * st;
      halfW = r;
    }
    // keep sub-pixel droplets at least ~1.5 px wide, trading size for opacity
    float pxPerUnit = uPxK / max(-mv.z, 0.1);
    float minW = 0.75 / pxPerUnit;
    float fix = 1.0;
    if (halfW < minW) { fix = halfW / minW; halfW = minW; }
    halfL = max(halfL, halfW);
    vBoost = 1.0 + 1.2 * sat(1.0 - halfW * pxPerUnit / 5.0);

    vec2 corner = position.xy * 2.0;
    mv.xy += axis * (corner.x * halfL) + vec2(-axis.y, axis.x) * (corner.y * halfW);
    gl_Position = projectionMatrix * mv;
    vUv = corner;
    vAxis = axis;
    vInfo = vec4(vis * aAux.y * fix, kind, seed, smoothstep(-3.5, 3.5, P.x));
  }
`;
const PARTICLE_FS = `
  uniform sampler2D uDropTex;
  uniform sampler2D uFxTex;
  uniform vec3 uRadKey;
  uniform vec3 uRadA;
  uniform vec3 uRadB;
  varying vec2 vUv;
  varying vec2 vAxis;
  varying vec4 vInfo;
  varying float vBoost;
  void main() {
    float r2 = dot(vUv, vUv);
    // rotate the sprite lookup back to screen space so highlights keep facing the lights
    vec2 s = vec2(vUv.x * vAxis.x - vUv.y * vAxis.y, vUv.x * vAxis.y + vUv.y * vAxis.x);
    vec3 tex = texture2D(uDropTex, s * (0.5 * DROP_K) + 0.5).rgb;
    float ca = cos(vInfo.z * 40.0);
    float sa = sin(vInfo.z * 40.0);
    vec2 sr = vec2(s.x * ca - s.y * sa, s.x * sa + s.y * ca);
    float sp = texture2D(uFxTex, sr * 0.5 + 0.5).r;
    float wisp = texture2D(uFxTex, sr * 0.21 + vec2(vInfo.z * 7.3, vInfo.z * 3.1)).g;
    if (r2 > 1.0) discard;
    float w = vInfo.w;
    vec3 radA = uRadA * (1.25 - 0.5 * w);
    vec3 radB = uRadB * (0.75 + 0.5 * w);
    vec3 col;
    float alpha;
    if (vInfo.y < 0.5) {
      // glassy droplet: baked light-response map (R = key, G = cyan rim, B = magenta rim)
      vec3 resp = tex * tex;
      col = (resp.r * uRadKey + resp.g * radA + resp.b * radB) * vBoost + vec3(0.016, 0.040, 0.058);
      alpha = sat(0.16 + 0.10 * r2 + lum(col) * 1.5) * (1.0 - smoothstep(0.86, 1.0, sqrt(r2)));
    } else if (vInfo.y < 1.5) {
      // back-lit wisp of vapor / mist
      col = ((radA + radB) * 0.030 + uRadKey * 0.014) * (0.7 + 0.6 * wisp);
      alpha = exp(-3.0 * r2) * (1.0 - r2) * smoothstep(0.24, 0.74, wisp) * 2.0;
    } else {
      // cluster of micro-droplets
      col = (radA + radB) * 0.030 + uRadKey * 0.012;
      alpha = sp * (1.0 - r2);
    }
    gl_FragColor = outColor(col, alpha * vInfo.x);
