/* ---- droplets / mist / micro-droplet clusters (InstancedMesh) ---------- */
const PARTICLE_VS = `
  attribute vec3 aQ;
  attribute vec3 aDev;
  attribute vec4 aTime;
  attribute vec4 aMisc;
  attribute vec4 aAux;
  attribute vec3 aChain;
  uniform float uPxK;
  varying vec2 vUv;
  varying vec2 vAxis;
  varying vec4 vInfo;
  varying vec4 vTex;
  varying vec3 vTexS;

  // Closed-form trajectory (position + velocity). Tracers ride the deforming water and are
  // released with a drag-limited deviation velocity; free particles are purely ballistic.
  vec3 particleAt(vec3 q, float a, out vec3 vel) {
    float t0 = aTime.x;
    float k = aTime.w;
    float ek = exp(-k * a);
    float gs = aMisc.z;
    vec3 p;
    vec3 v;
    if (aMisc.y < 3.5) {
      p = deformPV(q, aAux.x, uT0, uA0, v);
      p.y += (1.0 - gs) * max(uT0.z - fallOf(t0), 0.0);       // mist sinks slower than the free-fall frame
      v.y += (1.0 - gs) * uAd.w;
    } else {
      p = q;
      v = vec3(0.0);
      p.y -= gs * max(uT0.z - fallOf(t0) - fallVel(t0) * a, 0.0);
      v.y -= gs * max(uAd.w - fallVel(t0), 0.0);
    }
    vel = v + aDev * ek;
    return p + aDev * ((1.0 - ek) / k);
  }

  void main() {
    float t = uT0.x;
    float age = t - aTime.x;
    float life = aTime.z;
    float vis = smoothstep(0.0, aTime.y, age) * (1.0 - smoothstep(life * 0.55, life, age));
    if (vis < 0.002) {
      gl_Position = vec4(2.0, 2.0, 2.0, 1.0);
      vUv = vec2(0.0); vAxis = vec2(1.0, 0.0); vInfo = vec4(0.0); vTex = vec4(0.0); vTexS = vec3(0.0);
      return;
    }
    float kind = mod(aMisc.y, 4.0);
    float seed = aMisc.w;
    bool chain = dot(aChain, aChain) > 1e-9;
    float a = max(age, 0.0);
    vec3 vel;
    vec3 P = particleAt(aQ, a, vel);
    vec4 mv = viewMatrix * vec4(P, 1.0);
    // long axis: towards the next bead of the ligament (chains) or along the velocity
    vec3 dv = (viewMatrix * vec4(chain ? aChain : vel, 0.0)).xyz;
    float dl = length(dv.xy);
    vec2 axis = dl > 1e-6 ? dv.xy / dl : vec2(1.0, 0.0);
    float r = aMisc.x * (1.0 + aAux.z * a);
    float halfL;
    float halfW;
    if (kind < 0.5) {
      if (chain) {
        // Plateau-Rayleigh: the stretching ligament necks down between beads and
        // pinches off once the bead spacing exceeds ~pi diameters
        float Dk = (1.0 - exp(-aTime.w * a)) / aTime.w;
        float gap = length(aChain) * Dk;
        float fill = 1.0 - smoothstep(2.6, 5.2, gap / r);
        halfL = r + 0.55 * min(dl * Dk, 5.2 * r) * fill;
        halfW = r * mix(1.0, 0.64, fill);
      } else {
        float st = 1.0 + min(dl * 0.55, 1.8) * exp(-a / 0.45);
        st *= 1.0 + 0.20 * exp(-a / 0.9) * sin(a * (7.0 + 5.0 * seed) + seed * 40.0);   // shape oscillation
        halfL = r * st;
        halfW = r / sqrt(st);
      }
    } else {
      halfL = r * (1.0 + min(dl * 0.25, 1.2));
      halfW = r;
    }
    // keep sub-pixel droplets at least ~1.5 px wide, trading size for opacity
    float pxPerUnit = uPxK / max(-mv.z, 0.1);
    float minW = 0.75 / pxPerUnit;
    float fix = 1.0;
    if (halfW < minW) { fix = halfW / minW; halfW = minW; }
    halfL = max(halfL, halfW);

    vec2 corner = position.xy * 2.0;
    mv.xy += axis * (corner.x * halfL) + vec2(-axis.y, axis.x) * (corner.y * halfW);
    gl_Position = projectionMatrix * mv;
    vUv = corner;
    vAxis = axis;
    vInfo = vec4(vis * aAux.y * fix, kind, smoothstep(-3.5, 3.5, P.x), 1.0 + 1.2 * sat(1.0 - halfW * pxPerUnit / 5.0));

    // one atlas lookup per fragment: (centre, rotation) + (scale) of this sprite's window
    if (kind < 0.5) {
      vTex = vec4(ATLAS_DROP, 1.0, 0.0);
      vTexS = vec3(ATLAS_CELL * DROP_K, 0.0);
    } else {
      float ang = seed * 40.0;
      vec2 jitter = kind < 1.5 ? (fract(vec2(seed * 7.3, seed * 3.1)) - 0.5) : vec2(0.0);
      vTex = vec4(ATLAS_FX + jitter * ATLAS_CELL, cos(ang), sin(ang));
      vTexS = vec3(ATLAS_CELL * (kind < 1.5 ? 0.42 : 0.98), 0.0);
    }
  }
`;
const PARTICLE_FS = `
  uniform sampler2D uAtlas;
  uniform vec3 uRadKey;
  uniform vec3 uRadA;
  uniform vec3 uRadB;
  varying vec2 vUv;
  varying vec2 vAxis;
  varying vec4 vInfo;
  varying vec4 vTex;
  varying vec3 vTexS;
  void main() {
    float r2 = dot(vUv, vUv);
