        float m = length(vec2(TEAR_KH * vTear.x, vTear.y));
        float ang = atan(vTear.y, TEAR_KH * vHs + 1e-5);
        float star = 0.5 * sin(ang * 5.0 + 0.9) + 0.3 * sin(ang * 8.0 + 2.3) + 0.2 * sin(ang * 13.0 + 4.1);
        float jag = (vnoise(vRest * 5.0) - 0.5) * 0.16 + (vnoise(vRest * 13.0) - 0.5) * 0.04;
