        float bw = 0.030 + 0.06 * sat(uFront / 2.0);
        band = 1.0 - smoothstep(0.0, bw, e);
        vec3 wr = vec3(vnoise(vRest * 46.0), vnoise(vRest * 46.0 + 7.3), vnoise(vRest * 46.0 + 3.1)) - 0.5;
