function buildSimulation() {
  const rng = mulberry32(SEED);          // seed 42 — the only entropy source
  const rnd = function (a, b) { return a + (b - a) * rng(); };

  const renderer = new THREE.WebGLRenderer({ canvas: document.getElementById('stage'), antialias: true, alpha: true });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setSize(window.innerWidth, window.innerHeight, false);
  renderer.outputEncoding = THREE.sRGBEncoding;
  renderer.setClearColor(0x000000, 0);

  const scene = new THREE.Scene();
  const FOV = 35;                                    // ~85 mm equivalent, pure lateral view
  const camera = new THREE.PerspectiveCamera(FOV, window.innerWidth / window.innerHeight, 0.5, 60);
  const TAN_HALF = Math.tan(FOV * Math.PI / 360);
  const VIEW_HALF_H = 2.85, VIEW_MIN_HALF_W = 3.9;

  /* ---------------- lights ---------------- */
  LIGHT_RIG.forEach(function (L) {
    const light = new THREE.DirectionalLight(new THREE.Color(L.color[0], L.color[1], L.color[2]), L.power * 1.35);
    light.position.set(L.dir[0] * 12, L.dir[1] * 12, L.dir[2] * 12);
    light.name = L.name;
    scene.add(light);
  });
  scene.add(new THREE.AmbientLight(new THREE.Color(0.10, 0.12, 0.16), 1.0));

  /* ---------------- shared uniforms ---------------- */
  const U = {
    uT0: { value: new THREE.Vector4() },
    uA0: { value: new THREE.Vector4() },
    uAd: { value: new THREE.Vector4() },
    uRipple: { value: new THREE.Vector4() },
    uFront: { value: 0 },
    uTubeFade: { value: 1 },
    uBodyFade: { value: 1 },
    uPxK: { value: 1 },
    uExposure: { value: 1.0 },
    uLDir: { value: LIGHT_RIG.map(function (L) { return new THREE.Vector3().fromArray(L.dir); }) },
    uLRgt: { value: LIGHT_RIG.map(function (L) { return new THREE.Vector3().fromArray(L.right); }) },
    uLUp: { value: LIGHT_RIG.map(function (L) { return new THREE.Vector3().fromArray(L.up); }) },
    uLCol: { value: LIGHT_RIG.map(function (L) { return new THREE.Vector3().fromArray(L.rad); }) },
    uLSize: { value: LIGHT_RIG.map(function (L) { return new THREE.Vector2(L.size[0], L.size[1]); }) },
    uLSoft: { value: LIGHT_RIG.map(function (L) { return L.soft; }) },
    uBoxScale: { value: new THREE.Vector2(1, 1) },
    uAmbTop: { value: new THREE.Vector3(0.035, 0.042, 0.055) },
    uAmbBot: { value: new THREE.Vector3(0.012, 0.012, 0.016) }
  };
  const withShared = function (extra) { return Object.assign({}, U, extra || {}); };

  /* ---------------- latex membrane (Y-lathe) ---------------- */
  const skinPts = [];
  (function () {
    // rows: cosine-spaced, with extra resolution around the impact height
    const NB = 190, M = 2400, cdf = new Float64Array(M + 1);
    const uOf = function (s) { return 0.5 - 0.5 * Math.cos(Math.PI * s); };
    for (let i = 1; i <= M; i++) {
      const u = uOf((i - 0.5) / M);
      cdf[i] = cdf[i - 1] + 1 + 2.4 * Math.exp(-Math.pow((u - U_IMPACT) / 0.065, 2));
    }
    for (let j = 0; j <= NB; j++) {
      const target = cdf[M] * j / NB;
      let lo = 0, hi = M;
      while (hi - lo > 1) { const m = (lo + hi) >> 1; if (cdf[m] <= target) lo = m; else hi = m; }
      const u = uOf((lo + (target - cdf[lo]) / (cdf[hi] - cdf[lo])) / M);
      const n = bodyNormal2D(u);
      let r = bodyRadius(u) + SKIN_GAP * n[0];
      const y = Y_BOT + u * BODY_H + SKIN_GAP * n[1];
      r = Math.hypot(r, R_NECK * smoothstep(0.80, 0.985, u));
      skinPts.push({ r: j === 0 ? 0 : r, y: y });
    }
    const yTop = skinPts[skinPts.length - 1].y;
    for (let j = 1; j <= 6; j++) skinPts.push({ r: R_NECK, y: yTop + NECK_LEN * j / 6 });
  })();
  const Y_NECK_TOP = skinPts[skinPts.length - 1].y;
  const Y_SKIN_BOT = skinPts[0].y;

  function buildLatheY(pts, segs, dense) {
    // dense > 0 packs meridians towards phi = 0 (the impact side): phi(s) = 2pi s - dense sin(2pi s)
    const rows = pts.length, cols = segs + 1, count = rows * cols;
    const pos = new Float32Array(count * 3), nor = new Float32Array(count * 3);
    const uv = new Float32Array(count * 2), arc = new Float32Array(count);
    const arcs = [0];
    for (let j = 1; j < rows; j++) arcs[j] = arcs[j - 1] + Math.hypot(pts[j].r - pts[j - 1].r, pts[j].y - pts[j - 1].y);
    for (let j = 0; j < rows; j++) {
      const a = pts[Math.max(j - 1, 0)], b = pts[Math.min(j + 1, rows - 1)];
      const tr = b.r - a.r, ty = b.y - a.y, l = Math.hypot(tr, ty) || 1;
      const nr = ty / l, ny = -tr / l;
      for (let k = 0; k < cols; k++) {
        const phi = TAU * k / segs - (dense || 0) * Math.sin(TAU * k / segs);
        const c = Math.cos(phi), s = Math.sin(phi), i = j * cols + k;
        pos[i * 3] = pts[j].r * c; pos[i * 3 + 1] = pts[j].y; pos[i * 3 + 2] = pts[j].r * s;
        nor[i * 3] = nr * c; nor[i * 3 + 1] = ny; nor[i * 3 + 2] = nr * s;
        uv[i * 2] = phi / TAU; uv[i * 2 + 1] = j / (rows - 1);
        arc[i] = arcs[j];
      }
    }
    const idx = new (count > 65535 ? Uint32Array : Uint16Array)((rows - 1) * segs * 6);
    let p = 0;
    for (let j = 0; j < rows - 1; j++) for (let k = 0; k < segs; k++) {
      const a = j * cols + k, b = (j + 1) * cols + k, c = a + 1, d = b + 1;
      idx[p++] = a; idx[p++] = b; idx[p++] = c; idx[p++] = b; idx[p++] = d; idx[p++] = c;
    }
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    g.setAttribute('normal', new THREE.BufferAttribute(nor, 3));
    g.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
    g.setAttribute('aArc', new THREE.BufferAttribute(arc, 1));
    g.setIndex(new THREE.BufferAttribute(idx, 1));
    g.userData.arcs = arcs;
    return g;
  }
  const skinGeo = buildLatheY(skinPts, 224, 0.72);

  // impact station on the skin + retraction speed (must clear the whole membrane by T_SKIN_END)
  (function () {
    const arcs = skinGeo.userData.arcs;
    let mMax = 0;
    for (let j = 1; j < skinPts.length; j++) {
      if (skinPts[j - 1].y <= 0 && skinPts[j].y > 0) {
        ARC_I = lerp(arcs[j - 1], arcs[j], (0 - skinPts[j - 1].y) / (skinPts[j].y - skinPts[j - 1].y));
      }
    }
    for (let j = 0; j < skinPts.length; j++) {
      mMax = Math.max(mMax, Math.hypot(TEAR_KH * skinPts[j].r * Math.PI, arcs[j] - ARC_I));
    }
    // 0.12 covers the ragged-edge noise so nothing is left over; kept at 3-5x the fluid speed
    SKIN_SPEED = clamp((mMax + 0.12) / (T_SKIN_END - T_PUNCT - 0.02), 3.0 * FLUID_SPEED, 5.0 * FLUID_SPEED);
  })();
  const T_SCRAP = T_PUNCT + ARC_I / SKIN_SPEED;       // lower tear front reaches the nipple
  const T_RELEASE = T_SKIN_END - 0.07;                // upper tear front reaches the tether knot
  const T_BODY_GONE = T_BRK0 + T_BRK1 + 0.25;         // every sheet has ruptured into droplets

  const DEFS = glslDefines();
  const VS_COMMON = DEFS + GLSL_UTIL + GLSL_FIELD + GLSL_DEFORM;
  const FS_COMMON = DEFS + GLSL_UTIL + GLSL_ENV;

  const LATEX = new THREE.Color('#e61c24').convertSRGBToLinear();      // deep crimson
  const latexUniforms = function (side, solid) {
    return withShared({
      uSide: { value: side },
      uSolid: { value: solid },
      uLatex: { value: new THREE.Vector3(LATEX.r, LATEX.g, LATEX.b) },
      uLatexDeep: { value: new THREE.Vector3(LATEX.r * 0.42, LATEX.g * 0.30, LATEX.b * 0.40) },
      uLatexGlow: { value: new THREE.Vector3(1.0, 0.020, 0.026) }
    });
  };
  const skinFront = new THREE.Mesh(skinGeo, new THREE.ShaderMaterial({
    uniforms: latexUniforms(1, 0), vertexShader: VS_COMMON + SKIN_VS, fragmentShader: FS_COMMON + LATEX_FS,
    transparent: true, depthWrite: false, side: THREE.FrontSide
  }));
  const skinBack = new THREE.Mesh(skinGeo, new THREE.ShaderMaterial({
    uniforms: latexUniforms(-1, 0), vertexShader: VS_COMMON + SKIN_VS, fragmentShader: FS_COMMON + LATEX_FS,
    transparent: true, depthWrite: false, side: THREE.BackSide
  }));
  skinBack.renderOrder = 1; skinFront.renderOrder = 6;
  skinBack.frustumCulled = skinFront.frustumCulled = false;
  scene.add(skinBack, skinFront);

  /* ---------------- water body (polar grid about the bullet axis) ---------------- */
  const NT = 144;
  const A_MIN = Math.asin(RHO_MIN / X_EW);

