226	   *    backwards, re-firing, or running on 60 Hz / 120 Hz displays therefore
227	   *    produces bit-identical frames for a given simTime.
228	   * ======================================================================== */
229	  const DURATION = 8.000;
230	  const SEED = 42;
231	  const COUNTDOWN_SECONDS = 3.000;
232	  const REFIRE_HOLD_SECONDS = 1.000;
233	  const MAX_FRAME_DT = 0.1;
234	
235	  const T_CONTACT  = 1.000;   // bullet tip touches the latex
236	  const T_PUNCT    = 1.150;   // elastic limit reached: puncture, tear starts
237	  const T_SKIN_END = 1.600;   // latex fully retracted (tether + base)
238	  const T_CAV      = 2.400;   // cavitation tunnel onset (end of inertial stasis)
239	  const T_EXIT     = 3.800;   // tip emerges from the left boundary
240	  const T_BREAK    = 5.000;   // sheet / ligament disintegration onset
241	
242	  /* ==========================================================================
243	   * 2. DETERMINISTIC PRNG (Mulberry32, seed 42) — Math.random() is never used.
244	   *    All random numbers are drawn once, in a fixed order, while the scene is
245	   *    built; nothing is re-rolled at runtime.
246	   * ======================================================================== */
247	  function mulberry32(seed) {
248	    let a = seed >>> 0;
249	    return function () {
250	      a = (a + 0x6D2B79F5) | 0;
251	      let t = Math.imul(a ^ (a >>> 15), 1 | a);
252	      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
253	      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
254	    };
255	  }
256	
257	  const clamp = (x, a, b) => Math.min(b, Math.max(a, x));
258	  const lerp = (a, b, t) => a + (b - a) * t;
259	  const smoothstep = (a, b, x) => { const t = clamp((x - a) / (b - a), 0, 1); return t * t * (3 - 2 * t); };
260	  const TAU = Math.PI * 2;
261	
262	  /* ==========================================================================
263	   * 3. REST GEOMETRY OF THE BALLOON (teardrop with hydrostatic sag)
264	   *    r(u) = K * u^0.5 * (1-u)^0.9 ,  u = normalised height.
265	   *    The widest station sits at u = 0.357 (heavy, wide bottom); the top
266	   *    tapers into the neck. The bullet axis is the world X axis (y = z = 0).
267	   * ======================================================================== */
268	  const BODY_R = 1.15, BODY_H = 2.75, Y_BOT = -1.18, Y_TOP = Y_BOT + BODY_H;
269	  const PROF_A = 0.5, PROF_B = 0.9;
270	  const U_WIDE = PROF_A / (PROF_A + PROF_B);
271	  const PROF_K = BODY_R / (Math.pow(U_WIDE, PROF_A) * Math.pow(1 - U_WIDE, PROF_B));
272	  const SKIN_GAP = 0.014, R_NECK = 0.068, NECK_LEN = 0.13;
273	
274	  function bodyRadius(u) {
275	    u = clamp(u, 0, 1);
276	    return PROF_K * Math.pow(u, PROF_A) * Math.pow(1 - u, PROF_B);
