      U.uPxK.value = (h * renderer.getPixelRatio() * 0.5) / TAN_HALF;
    }

    /* ---------------- renderAt(simTime): the whole show as a pure function ---------------- */
    const SPIN = 2.1;                                   // rad of rifling spin per unit travelled
    function packTime(T, A, t) {
      T.set(t, tipX(t), fallDist(t), dimpleAmt(t));
      const kb = 1 - Math.exp(-Math.max(t - T_BURST, 0) / TAU_BURST);
      A.set(LIP_E * (1 - Math.exp(-Math.max(t - T_CAV, 0) / TAU_LE)),        // entry crown length
            LIP_X * (1 - Math.exp(-Math.max(t - T_EXIT, 0) / TAU_LX)),       // exit cone length
            E_MAX * kb * kb,                                                 // burst expansion
            BULGE * smoothstep(T_EXIT - 0.60, T_EXIT - 0.02, t));            // water pushed ahead of the tip
    }
    const prevT = new THREE.Vector4(), prevA = new THREE.Vector4();
    function renderAt(simTime) {
      const t = clamp(simTime, 0, DURATION);
      packTime(prevT, prevA, t - DT_VEL);
      packTime(U.uT0.value, U.uA0.value, t);
      const A = U.uA0.value;                              // analytic rates of the crown / burst / fall terms
      U.uAd.value.set((A.x - prevA.x) / DT_VEL, (A.y - prevA.y) / DT_VEL, (A.z - prevA.z) / DT_VEL,
                      (U.uT0.value.z - prevT.z) / DT_VEL);
      U.uFront.value = SKIN_SPEED * Math.max(t - T_PUNCT, 0);
      U.uTubeFade.value = 1 - smoothstep(4.5, 5.6, t);
      const tw = Math.max(t - T_PUNCT, 0), tc = Math.max(t - T_CAV, 0);
      U.uRipple.value.set(0.010 * smoothstep(0, 0.2, tw) * Math.exp(-tw / 1.4), tw,
                          0.016 * smoothstep(0, 0.4, tc) * Math.exp(-tc / 1.6), tc);
      // the water only needs drawing once the latex starts to give way (it is hidden before)
      U.uBodyFade.value = smoothstep(T_CONTACT, T_PUNCT, t);
      bodyFront.visible = bodyBack.visible = t > T_CONTACT && t < T_BODY_GONE;
      particles.visible = t > T_PUNCT;

      const tx = tipX(t);
      bullet.position.set(tx, 0, 0);
      bullet.rotation.x = SPIN * (X_START - tx);
      const speed = (tipX(t - 0.005) - tipX(t + 0.005)) / 0.01;
      streak.position.set(tx, 0, 0);
      streak.visible = speed > 2.6;
      streakU.uStreak.value.set(Math.min(speed * 0.05, 0.9), 0.40 * smoothstep(2.6, 10.0, speed));

      skinFront.visible = t < T_SKIN_END + 0.05;
      skinBack.visible = skinFront.visible && t > T_CONTACT;     // inner far wall only shows through the tear
      tube.visible = t > T_PUNCT && U.uTubeFade.value > 0.001;

      // tether recoil once the membrane lets go; shrivelled latex snaps up to the knot
      const tr = t - T_RELEASE;
      let bounce = 0, sway = 0, swing = 0, ragScale = 0;
      if (tr > 0) {
        bounce = 0.060 * (1 - Math.exp(-tr / 0.05)) + 0.030 * Math.exp(-tr / 0.7) * Math.sin(11.0 * tr);
        sway = 0.0055 * Math.exp(-tr / 3.0) * Math.sin(2.6 * tr);
        swing = 0.55 * Math.exp(-tr / 1.1) * Math.sin(6.0 * tr + 1.2) + 0.05 * Math.exp(-tr / 6.0) * Math.sin(1.9 * tr);
        const k = clamp(tr / 0.13, 0, 1), c1 = 1.70158, c3 = c1 + 1;
        ragScale = 1 + c3 * Math.pow(k - 1, 3) + c1 * Math.pow(k - 1, 2);      // ease-out-back snap
      }
      rig.position.y = Y_ANCHOR + bounce;
      rig.rotation.z = sway;
      ragPivot.visible = ragScale > 0.001;
      ragPivot.scale.set(0.55 + 0.45 * ragScale, Math.max(ragScale, 0.001), 0.55 + 0.45 * ragScale);
      ragPivot.rotation.z = swing;

      // base scrap: flung downward by its own retraction momentum, tumbling
      const ts = t - T_SCRAP;
      scrap.visible = ts > 0;
      if (ts > 0) {
        const travel = 0.62 * SKIN_SPEED * (1 - Math.exp(-1.3 * ts)) / 1.3;
        scrap.position.set(0.10 * travel, Y_SKIN_BOT - 0.02 - travel - fallDist(t), 0.06 * travel);
        scrap.rotation.set(5.2 * ts, 3.1 * ts, 1.2 + 7.3 * ts);
        scrap.scale.setScalar(smoothstep(0, 0.06, ts));
        if (scrap.position.y < -7) scrap.visible = false;
      }

      renderer.render(scene, camera);
    }

    resize();
    window.addEventListener('resize', function () { resize(); renderAt(currentSimTime()); });
    renderer.compile(scene, camera);
    return renderAt;
  }

  /* ==========================================================================
   * 8. PLAYBACK STATE MACHINE & DOCK
   * ======================================================================== */
  const dom = {
    countdown: document.getElementById('countdown'),
    refire: document.getElementById('btn-refire'),
    toggle: document.getElementById('btn-toggle'),
    iconPause: document.getElementById('icon-pause'),
    iconPlay: document.getElementById('icon-play'),
    scrubber: document.getElementById('scrubber'),
    pills: Array.prototype.slice.call(document.querySelectorAll('.speed-pill'))
  };

  const COUNTDOWN = 'COUNTDOWN', PLAYING = 'PLAYING', PAUSED = 'PAUSED', REFIRE_HOLD = 'REFIRE_HOLD', ENDED = 'ENDED';
  let state = null;                 // null until the first animation frame after the resting render
  let simTime = 0.000;
  let playbackSpeed = 1.0;
  let countdownElapsed = 0;         // wall-clock seconds, unaffected by playbackSpeed
  let holdElapsed = 0;              // wall-clock seconds, unaffected by playbackSpeed
  let phaseStart = null;            // frame timestamp (ms) at which COUNTDOWN / REFIRE_HOLD began
  let lastStamp = null;
  let shownDigit = null;
  function currentSimTime() { return simTime; }

  let renderAt = function () {};
  try {
    renderAt = buildSimulation();
  } catch (err) {
    if (window.console && console.error) console.error('WebGL scene could not be created:', err);
  }

  function setToggleIcon(showPause) {
    dom.iconPause.style.display = showPause ? '' : 'none';
    dom.iconPlay.style.display = showPause ? 'none' : '';
    dom.toggle.setAttribute('aria-label', showPause ? 'Pause' : 'Play');
  }
  function showCountdown(digit) {
    if (shownDigit === digit) return;
    shownDigit = digit;
    dom.countdown.textContent = String(digit);
    dom.countdown.style.display = 'block';
  }
  function hideCountdown() {
    shownDigit = null;
    dom.countdown.style.display = 'none';
    dom.countdown.textContent = '';
  }
  function resetToStart() {
    simTime = 0.000;
    dom.scrubber.value = '0';
  }
  function advance(dt) {
    simTime = Math.min(DURATION, simTime + dt * playbackSpeed);
    dom.scrubber.value = simTime.toFixed(3);
    if (simTime >= DURATION) {
      simTime = DURATION;
      dom.scrubber.value = DURATION.toFixed(3);
      state = ENDED;
      setToggleIcon(false);
    }
  }

  function frame(stamp) {
    requestAnimationFrame(frame);
    if (lastStamp === null) lastStamp = stamp;
    const dt = Math.min(Math.max((stamp - lastStamp) / 1000, 0), MAX_FRAME_DT);
    lastStamp = stamp;

    if (state === null) {                                   // first frame after the resting scene rendered
      state = COUNTDOWN;
      phaseStart = stamp;
      countdownElapsed = 0;
      setToggleIcon(true);
    }
    if (state === COUNTDOWN) {
      countdownElapsed = Math.max(0, (stamp - phaseStart) / 1000);
      if (countdownElapsed >= COUNTDOWN_SECONDS) {
        hideCountdown();
        state = PLAYING;
        advance(Math.min(countdownElapsed - COUNTDOWN_SECONDS, MAX_FRAME_DT));
      } else {
        showCountdown(3 - Math.floor(countdownElapsed));    // "3", "2", "1"
      }
    } else if (state === REFIRE_HOLD) {
      if (phaseStart === null) phaseStart = stamp;          // hold clock starts on the first frame after the click
      holdElapsed = Math.max(0, (stamp - phaseStart) / 1000);
      if (holdElapsed >= REFIRE_HOLD_SECONDS) {
        state = PLAYING;
        advance(Math.min(holdElapsed - REFIRE_HOLD_SECONDS, MAX_FRAME_DT));
      }
    } else if (state === PLAYING) {
      advance(dt);
    }
    renderAt(simTime);
  }

  dom.toggle.addEventListener('click', function () {
    if (state === PLAYING) {
      state = PAUSED;
      setToggleIcon(false);
    } else if (state === COUNTDOWN || state === REFIRE_HOLD || state === null) {
      hideCountdown();
      resetToStart();
      state = PAUSED;
      setToggleIcon(false);
      renderAt(simTime);
    } else if (state === PAUSED) {
      state = PLAYING;
      setToggleIcon(true);
    } else if (state === ENDED) {
      hideCountdown();
      resetToStart();
      state = PLAYING;
      setToggleIcon(true);
      renderAt(simTime);
    }
  });

  dom.refire.addEventListener('click', function () {
    hideCountdown();
    resetToStart();
    renderAt(simTime);                                      // exact resting state, immediately
    setToggleIcon(true);
    state = REFIRE_HOLD;
    holdElapsed = 0;
    phaseStart = null;
  });

  dom.pills.forEach(function (pill) {
    pill.addEventListener('click', function () {
      playbackSpeed = parseFloat(pill.getAttribute('data-speed'));
      dom.pills.forEach(function (other) {
        const on = other === pill;
        other.classList.toggle('is-active', on);
        other.setAttribute('aria-checked', on ? 'true' : 'false');
      });
    });
  });

  dom.scrubber.addEventListener('input', function () {
    hideCountdown();
    const v = parseFloat(dom.scrubber.value);
    simTime = clamp(isFinite(v) ? v : 0, 0, DURATION);
    state = PAUSED;
    setToggleIcon(false);
    renderAt(simTime);
  });

  renderAt(simTime);                 // initial resting scene (simTime = 0.000)
  requestAnimationFrame(frame);      // COUNTDOWN starts on the first frame after it
})();
</script>
</body>
</html>

