1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Ballistics Water Balloon — 15,000 FPS Slow-Motion</title>
7	<style>
8	*, *::before, *::after {
9	  box-sizing: border-box;
10	}
11	html, body {
12	  margin: 0;
13	  padding: 0;
14	  width: 100%;
15	  height: 100%;
16	  overflow: hidden;
17	  background: radial-gradient(circle at center, #161922 0%, #090a0f 100%);
18	  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
19	  -webkit-font-smoothing: antialiased;
20	  -webkit-user-select: none;
21	  user-select: none;
22	}
23	#stage {
24	  display: block;
25	  width: 100vw;
26	  height: 100vh;
27	}
28	
29	#countdown {
30	  position: fixed;
31	  top: 50%;
32	  left: 50%;
33	  transform: translate(-50%, -50%);
34	  z-index: 50;
35	  pointer-events: none;
36	  font-size: 96px;
37	  font-weight: 700;
38	  line-height: 1;
39	  color: rgba(255, 255, 255, 0.35);
40	  font-variant-numeric: tabular-nums;
41	}
42	
43	#dock {
44	  position: fixed;
45	  bottom: 24px;
46	  left: 50%;
47	  transform: translateX(-50%);
48	  z-index: 100;
49	  width: 536px;
50	  height: 44px;
51	  display: flex;
52	  align-items: center;
53	  justify-content: space-between;
54	  gap: 10px;
55	  padding: 0 14px;
56	  background: rgba(15, 17, 23, 0.78);
57	  backdrop-filter: blur(12px);
58	  -webkit-backdrop-filter: blur(12px);
59	  border: 1px solid rgba(255, 255, 255, 0.12);
60	  border-radius: 9999px;
61	  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.35);
62	}
63	
64	#dock button {
65	  font-family: inherit;
66	  line-height: 1;
67	  margin: 0;
68	  flex-shrink: 0;
69	  white-space: nowrap;
70	  appearance: none;
71	  -webkit-appearance: none;
72	}
73	
74	.dock-sep {
75	  width: 1px;
76	  height: 18px;
77	  flex-shrink: 0;
78	  background: rgba(255, 255, 255, 0.12);
79	}
80	
81	#btn-refire {
82	  width: 78px;
83	  height: 28px;
84	  padding: 0 10px;
85	  display: inline-flex;
86	  align-items: center;
87	  justify-content: center;
88	  gap: 5px;
89	  background: rgba(255, 255, 255, 0.08);
90	  border: 1px solid rgba(255, 255, 255, 0.12);
91	  border-radius: 9999px;
92	  color: #ffffff;
93	  font-size: 12px;
94	  font-weight: 500;
95	  cursor: pointer;
96	}
97	#btn-refire:hover {
98	  background: rgba(255, 255, 255, 0.16);
99	}
100	
101	#btn-toggle {
102	  width: 28px;
103	  height: 28px;
104	  padding: 0;
105	  display: inline-flex;
106	  align-items: center;
107	  justify-content: center;
108	  background: rgba(255, 255, 255, 0.08);
109	  border: 1px solid rgba(255, 255, 255, 0.12);
